// Populate these from your own dashboards/MCP exports (manual). Numbers are examples only.
return [{ json: {
  date: '2026-09-23',
  downloads_7d: 2459,
  revenue_7d_usd: 4289,
  ad_spend_usd: 475,
  roas: 1.5,
  posts_per_day: 3,
  support_emails: 16,
  support_resolved: 13,
  open_prs: 1
} }];

const j = $input.first().json;
const e = [];
if (!/^\d{4}-\d{2}-\d{2}$/.test(j.date||'')) e.push('date must be YYYY-MM-DD');
for (const k of ['downloads_7d','revenue_7d_usd','ad_spend_usd','roas','support_emails','support_resolved']) if (!Number.isFinite(j[k])) e.push(k + ' must be a number');
if (Number.isFinite(j.support_resolved) && Number.isFinite(j.support_emails) && j.support_resolved > j.support_emails) e.push('support_resolved cannot exceed support_emails');
if (e.length) throw new Error('Invalid metrics: ' + e.join('; '));
return [{ json: j }];

const raw = $json && $json.content && $json.content[0] && $json.content[0].text;
if (!raw || !raw.trim()) throw new Error('Anthropic returned empty brief');
const date = $('Validate Metrics').first().json.date;
return [{ json: { subject: 'Daily brief - ' + date, body: raw.trim() } }];
